import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/p_matematica-per-informatica/pb/pbfa.md","filePath":"lezioni/p_matematica-per-informatica/pb/pbfa.md"}`),a={name:`lezioni/p_matematica-per-informatica/pb/pbfa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione" tabindex="-1">Introduzione <a class="header-anchor" href="#introduzione" aria-label="Permalink to “Introduzione”">​</a></h1><p>Il sistema binario fu pensato come idea matematica senza applicazioni pratiche già nel diciassettesimo secolo, ma fu soltanto con Boole e poi con la nascita dell&#39;informatica che acquisì l&#39;importanza che oggi gli compete, quale sistema di numerazione ormai più utilizzato nel mondo.</p><p>Intuitivamente possiamo dire che la sua importanza deriva dal fatto che è possibile far &quot;ricordare&quot; ad un circuito che è stato percorso da una corrente, ad esempio facendo attivare, al passaggio di corrente, una piccola &quot;calamita&quot; e quindi possiamo associare la cifra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> al fatto della calamita non attivata e la cifra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> alla calamita attivata.</p><p>Così è possibile avere una memoria che un&#39;altra corrente, passando per il circuito potrà leggere e magari, con un circuito opportuno che operi sui dati che incontra, trasformare in altri dati.</p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};